def find_original_array(changed: List[int]) -> List[int]:
    if len(changed) % 2:
        return []
    top = max(changed)
    count = [0] * (top + 1)
    for v in changed:
        count[v] += 1
    if count[0] % 2:
        return []                       # zeros must pair with zeros
    original = [0] * (count[0] // 2)
    for x in range(1, top + 1):
        c = count[x]
        if c == 0:
            continue
        double = 2 * x
        # Every remaining copy of x is original and needs its double.
        if double > top or count[double] < c:
            return []
        count[double] -= c
        original.extend([x] * c)
    return original

def count_good_subarrays(nums: List[int]) -> int:
    n = len(nums)
    left = [-1] * n      # nearest j < i with nums[j] not a subset of nums[i], or equal to it
    right = [n] * n      # nearest j > i with nums[j] not a subset of nums[i]
    stack = []
    for i, v in enumerate(nums):
        while stack and nums[stack[-1]] != v and nums[stack[-1]] | v == v:
            stack.pop()                      # proper subsets of v are shadowed by i
        left[i] = stack[-1] if stack else -1
        stack.append(i)
    stack = []
    for i in range(n - 1, -1, -1):
        v = nums[i]
        while stack and nums[stack[-1]] | v == v:
            stack.pop()                      # subsets (including equal values) are shadowed
        right[i] = stack[-1] if stack else n
        stack.append(i)
    # Each good subarray is counted at the leftmost position holding its OR.
    return sum((i - left[i]) * (right[i] - i) for i in range(n))

