def minimum_time(time: List[int], total_trips: int) -> int:
    buses = list(Counter(time).items())    # (trip duration, how many buses)
    lo, hi = 1, min(time) * total_trips     # hi is always feasible
    while lo < hi:
        mid = (lo + hi) // 2
        done = 0
        for duration, copies in buses:
            done += (mid // duration) * copies
            if done >= total_trips:
                break
        if done >= total_trips:
            hi = mid                          # mid is enough; try smaller
        else:
            lo = mid + 1
    return lo

