def json_parse(s: str) -> Any:
    NUM_CHARS = set("-+.eE0123456789")
    stack = []           # frames: [container, pending_key_or_None]
    result = None
    i, n = 0, len(s)

    def attach(value):
        nonlocal result
        if not stack:
            result = value
            return
        frame = stack[-1]
        container = frame[0]
        if isinstance(container, list):
            container.append(value)
        else:
            container[frame[1]] = value
            frame[1] = None

    while i < n:
        ch = s[i]
        if ch == "{" or ch == "[":
            stack.append([{} if ch == "{" else [], None])
            i += 1
        elif ch == "}" or ch == "]":
            container = stack.pop()[0]
            attach(container)
            i += 1
        elif ch == "," or ch == ":":
            i += 1
        elif ch == '"':
            end = s.index('"', i + 1)
            text = s[i + 1:end]
            i = end + 1
            top = stack[-1] if stack else None
            if top is not None and isinstance(top[0], dict) and top[1] is None:
                top[1] = text                  # this string is an object key
            else:
                attach(text)
        elif ch == "t":
            attach(True); i += 4
        elif ch == "f":
            attach(False); i += 5
        elif ch == "n":
            attach(None); i += 4
        else:
            j = i
            while j < n and s[j] in NUM_CHARS:
                j += 1
            token = s[i:j]
            is_float = "." in token or "e" in token or "E" in token
            attach(float(token) if is_float else int(token))
            i = j
    return result

