def three_equal_parts(arr: List[int]) -> List[int]:
    n = len(arr)
    total = sum(arr)
    if total == 0:
        return [0, n - 1]            # every part is worth zero
    if total % 3:
        return [-1, -1]
    k = total // 3
    # index of the first one in each of the three parts
    starts = []
    ones = 0
    for idx, bit in enumerate(arr):
        if bit == 1:
            if ones in (0, k, 2 * k):
                starts.append(idx)
            ones += 1
    p1, p2, p3 = starts
    # the third part runs to the end, so walk all three until it does
    while p3 < n and arr[p1] == arr[p2] == arr[p3]:
        p1 += 1
        p2 += 1
        p3 += 1
    if p3 == n:
        return [p1 - 1, p2]
    return [-1, -1]

