def min_swaps(data: List[int]) -> int:
    k = sum(data)
    if k <= 1:
        return 0
    ones_in_window = sum(data[:k])
    best = ones_in_window
    for right in range(k, len(data)):
        # slide the window one step: data[right] enters, data[right - k] leaves
        ones_in_window += data[right] - data[right - k]
        if ones_in_window > best:
            best = ones_in_window
    return k - best

