def count_pairs(n: int, edges: List[List[int]]) -> int:
    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb:
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

    pairs = 0
    seen = 0
    for v in range(n):
        if parent[v] == v:                  # v is the root of a component
            pairs += size[v] * seen
            seen += size[v]
    return pairs

