def count_triplets(nums: List[int]) -> int:
    FULL = (1 << 16) - 1
    freq = list(Counter(nums).items())
    # pair[v]: number of ordered index pairs whose AND equals v
    pair = Counter()
    for a, ca in freq:
        for b, cb in freq:
            pair[a & b] += ca * cb

    total = 0
    for x, cx in freq:
        free = FULL & ~x                  # bits a matching pair value may use
        if (1 << bin(free).count("1")) <= len(pair):
            ways = 0
            sub = free
            while True:                   # enumerate every submask of free
                ways += pair.get(sub, 0)
                if sub == 0:
                    break
                sub = (sub - 1) & free
        else:
            ways = sum(c for v, c in pair.items() if v & x == 0)
        total += cx * ways
    return total

