def minimize_xor(num1: int, num2: int) -> int:
    budget = bin(num2).count("1")
    x = 0
    # match num1's highest set bits first
    for bit in range(31, -1, -1):
        if budget and num1 >> bit & 1:
            x |= 1 << bit
            budget -= 1
    # leftover ones go to the lowest positions that are still zero
    bit = 0
    while budget:
        if not x >> bit & 1:
            x |= 1 << bit
            budget -= 1
        bit += 1
    return x

