def max_genetic_difference(parents: List[int], queries: List[List[int]]) -> List[int]:
    n = len(parents)
    children = [[] for _ in range(n)]
    root = -1
    for x, p in enumerate(parents):
        if p == -1:
            root = x
        else:
            children[p].append(x)
    asked = [[] for _ in range(n)]
    for qi, (node, val) in enumerate(queries):
        asked[node].append((val, qi))

    HIGH = 17                          # bits 17..0 cover values below 2^18
    nxt = [[0, 0]]                     # trie child pointers, 0 means missing
    cnt = [0]                          # live values passing through each trie node

    def update(x, delta):
        cur = 0
        for b in range(HIGH, -1, -1):
            bit = (x >> b) & 1
            if nxt[cur][bit] == 0:
                nxt.append([0, 0])
                cnt.append(0)
                nxt[cur][bit] = len(nxt) - 1
            cur = nxt[cur][bit]
            cnt[cur] += delta

    def best_xor(val):
        cur, res = 0, 0
        for b in range(HIGH, -1, -1):
            bit = (val >> b) & 1
            other = nxt[cur][bit ^ 1]
            if other and cnt[other] > 0:
                res |= 1 << b
                cur = other
            else:
                cur = nxt[cur][bit]
        return res

    ans = [0] * len(queries)
    stack = [(root, False)]
    while stack:
        node, leaving = stack.pop()
        if leaving:
            update(node, -1)           # node is no longer an ancestor
            continue
        update(node, 1)
        for val, qi in asked[node]:
            ans[qi] = best_xor(val)
        stack.append((node, True))
        for c in children[node]:
            stack.append((c, False))
    return ans

def sum_remoteness(grid: List[List[int]]) -> int:
    n = len(grid)
    total = sum(v for row in grid for v in row if v > 0)
    seen = [[False] * n for _ in range(n)]
    answer = 0
    for si in range(n):
        for sj in range(n):
            if grid[si][sj] == -1 or seen[si][sj]:
                continue
            # BFS over one component, tracking its size and value sum.
            seen[si][sj] = True
            queue = [(si, sj)]
            part = 0
            for i, j in queue:
                part += grid[i][j]
                for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                    if 0 <= ni < n and 0 <= nj < n and not seen[ni][nj] and grid[ni][nj] != -1:
                        seen[ni][nj] = True
                        queue.append((ni, nj))
            answer += len(queue) * (total - part)
    return answer

