def min_operations(nums: List[int], target: int) -> int:
    if sum(nums) < target:
        return -1
    cnt = [0] * 33
    for x in nums:
        cnt[x.bit_length() - 1] += 1
    ops = 0
    for i in range(31):
        if target >> i & 1:
            if cnt[i]:
                cnt[i] -= 1
            else:
                # Split the smallest larger power down to 2^i.
                j = i + 1
                while cnt[j] == 0:
                    j += 1
                ops += j - i
                cnt[j] -= 1
                for t in range(i + 1, j):
                    cnt[t] += 1        # one leftover copy at each middle level
                # the two copies of 2^i: one is used now, one is left over
                cnt[i] += 1
        cnt[i + 1] += cnt[i] // 2      # pair leftovers into the next power
    return ops

def maximum_gap(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return 0
    lo, hi = min(nums), max(nums)
    if lo == hi:
        return 0
    size = max(1, (hi - lo) // (n - 1))      # bucket width, never above the average gap
    count = (hi - lo) // size + 1
    bmin = [None] * count
    bmax = [None] * count
    for x in nums:
        b = (x - lo) // size
        if bmin[b] is None:
            bmin[b] = bmax[b] = x
        else:
            if x < bmin[b]:
                bmin[b] = x
            if x > bmax[b]:
                bmax[b] = x
    best = 0
    prev_max = lo
    for b in range(count):
        if bmin[b] is None:
            continue
        best = max(best, bmin[b] - prev_max)  # gap across the empty stretch
        prev_max = bmax[b]
    return best

