def rotated_digits(n: int) -> int:
    digits = list(map(int, str(n)))

    def count_upto(allowed):
        """How many numbers in [0, n] use only digits from `allowed`."""
        total = 0
        k = len(allowed)
        for pos, d in enumerate(digits):
            rest = len(digits) - pos - 1
            smaller = sum(1 for a in allowed if a < d)
            total += smaller * k ** rest
            if d not in allowed:
                return total       # n's own prefix is no longer possible
        return total + 1           # n itself qualifies

    valid = {0, 1, 2, 5, 6, 8, 9}
    same = {0, 1, 8}
    return count_upto(valid) - count_upto(same)

