def min_moves_to_make_palindrome(s: str) -> int:
    moves = 0
    while len(s) > 1:
        j = s.rfind(s[0])
        if j == 0:
            # Unique letter: it belongs in the middle.
            moves += len(s) // 2
            s = s[1:]
        else:
            moves += len(s) - 1 - j      # swap the partner to the right end
            s = s[1:j] + s[j + 1:]       # both ends are now fixed
    return moves

